def _secret_revision(*values: str) -> str:
    raw = "|".join(str(v or "").strip() for v in values)
    return hashlib.sha1(raw.encode("utf-8")).hexdigest()[:12]


def _market_cache_ttl(module_code: str, *, fast_mode: bool = False) -> int:
    base = int(_MARKET_CACHE_TTL_SEC.get(str(module_code or "").strip(), 120))
    if fast_mode:
        return max(45, int(base * 0.7))
    return base


_FEEDBACK_RATE_LIMIT_PAUSE_KEY = "feedback_rate_limit_pauses_v1"
_FEEDBACK_RATE_LIMIT_PAUSE_SEC = 45 * 60
_FEEDBACK_STALE_FALLBACK_SEC = 14 * 24 * 60 * 60
_MOJIBAKE_RE = re.compile(r"(Р |Рќ|Рџ|Рћ|Р‘|Р§|РЎ|РІР|Р°Р|РµР|Ð|Ñ|�)")


def _mojibake_score(value: str) -> int:
    text = str(value or "")
    if not text:
        return 0
    return sum(len(x) for x in _MOJIBAKE_RE.findall(text))


def _repair_text_encoding(value: str) -> str:
    text = str(value or "")
    if not text or _mojibake_score(text) <= 0:
        return text
    best = text
    best_score = _mojibake_score(best)
    current = text
    for _ in range(4):
        candidates: list[str] = []
        for encoding in ("cp1251", "latin1"):
            try:
                candidates.append(current.encode(encoding).decode("utf-8"))
            except Exception:
                continue
        improved = False
        for candidate in candidates:
            score = _mojibake_score(candidate)
            if score < best_score:
                best = candidate
                best_score = score
                current = candidate
                improved = True
                break
        if not improved:
            break
        if best_score <= 0:
            break
    return best


def _repair_payload_encoding(payload: Any) -> Any:
    if isinstance(payload, str):
        return _repair_text_encoding(payload)
    if isinstance(payload, list):
        return [_repair_payload_encoding(item) for item in payload]
    if isinstance(payload, dict):
        return {key: _repair_payload_encoding(value) for key, value in payload.items()}
    return payload


def _feedback_reply_http_error(message: Any) -> HTTPException:
    detail = _repair_text_encoding(str(message or "")).strip() or "Не удалось отправить ответ."
    lowered = detail.lower()
    status_code = 429 if ("429" in lowered or "too many requests" in lowered) else 400
    return HTTPException(status_code=status_code, detail=detail)


def _store_rate_limited_feedback_reply(
    db: Session,
    user: User,
    *,
    marketplace: str,
    item_type: str,
    item_external_id: str,
    reply_text: str,
    rating: int = 0,
    error: str = "",
) -> FeedbackAutoReplyLog:
    market = str(marketplace or "").strip().lower()[:30]
    kind = str(item_type or "review").strip().lower()[:30] or "review"
    item_id = str(item_external_id or "").strip()[:128]
    reply = sanitize_marketplace_reply_text(reply_text)
    payload = {
        "marketplace": market,
        "item_type": kind,
        "item_external_id": item_id,
        "rating": int(rating or 0),
        "manual_reply": True,
        "reply_text": reply,
    }
    log = db.scalar(
        select(FeedbackAutoReplyLog).where(
            FeedbackAutoReplyLog.user_id == int(user.id),
            FeedbackAutoReplyLog.marketplace == market,
            FeedbackAutoReplyLog.item_type == kind,
            FeedbackAutoReplyLog.item_external_id == item_id,
        )
    )
    if not log:
        log = FeedbackAutoReplyLog(
            user_id=int(user.id),
            marketplace=market,
            item_type=kind,
            item_external_id=item_id,
            rating=int(rating or 0),
            created_at=datetime.utcnow(),
        )
        db.add(log)
        db.flush()
    log.status = "queued"
    log.reply_text = reply[:3000]
    log.error = _repair_text_encoding(str(error or "WB API returned 429"))[:1000]
    log.payload_json = json.dumps(payload, ensure_ascii=False)
    log.updated_at = datetime.utcnow()
    db.add(log)
    return log


