def _feedback_pause_key(user_id: int, module_code: str, marketplace: str) -> str:
    return ":".join(
        [
            str(int(user_id or 0)),
            str(module_code or "").strip().lower(),
            str(marketplace or "").strip().lower(),
        ]
    )


def _feedback_pause_map(db: Session) -> dict[str, float]:
    try:
        payload = json.loads(_get_system_setting(db, _FEEDBACK_RATE_LIMIT_PAUSE_KEY) or "{}")
    except Exception:
        payload = {}
    if not isinstance(payload, dict):
        return {}
    now_ts = datetime.utcnow().timestamp()
    out: dict[str, float] = {}
    for key, value in payload.items():
        try:
            until = float(value or 0)
        except Exception:
            continue
        if until > now_ts:
            out[str(key)] = until
    if len(out) != len(payload):
        _set_system_setting(db, _FEEDBACK_RATE_LIMIT_PAUSE_KEY, json.dumps(out, ensure_ascii=False))
    return out


def _feedback_is_rate_limited(db: Session, *, user_id: int, module_code: str, marketplace: str) -> bool:
    key = _feedback_pause_key(user_id, module_code, marketplace)
    until = float(_feedback_pause_map(db).get(key) or 0.0)
    return until > datetime.utcnow().timestamp()


def _feedback_mark_rate_limited(db: Session, *, user_id: int, module_code: str, marketplace: str) -> None:
    pauses = _feedback_pause_map(db)
    until = datetime.utcnow().timestamp() + _FEEDBACK_RATE_LIMIT_PAUSE_SEC
    pauses[_feedback_pause_key(user_id, module_code, marketplace)] = until
    if str(marketplace or "").strip().lower() == "wb":
        # WB applies one shared limit to the whole Feedbacks/Questions category.
        for sibling_module in ("wb_reviews_ai", "wb_questions_ai"):
            pauses[_feedback_pause_key(user_id, sibling_module, "wb")] = until
    _set_system_setting(db, _FEEDBACK_RATE_LIMIT_PAUSE_KEY, json.dumps(pauses, ensure_ascii=False, sort_keys=True))


def _empty_feedback_rate_limit_payload(message: str) -> dict[str, Any]:
    return {"new": [], "answered": [], "warnings": [message]}


def _feedback_cache_warnings(cache_meta: dict[str, Any] | None) -> list[str]:
    meta = dict(cache_meta or {})
    source = str(meta.get("source") or "").lower()
    error = _repair_text_encoding(str(meta.get("error") or "")).strip()
    warnings: list[str] = []
    if "rate-limit" in source or "pause" in source or "429" in error or "too many requests" in error.lower():
        warnings.append(
            "WB временно ограничил запросы (429). "
            "Сервис поставил WB на паузу и не будет повторно дергать API до снятия лимита."
        )
    if meta.get("stale") and not warnings:
        warnings.append("Показаны последние сохраненные данные, потому что API маркетплейса временно недоступен.")
    return warnings


def _get_feedback_market_cache(
    db: Session,
    *,
    user_id: int,
    module_code: str,
    marketplace: str,
    cache_key: str,
    ttl_sec: int,
    fetcher: Callable[[], Any],
    stale_if_error_sec: int = 20 * 60,
    prefer_stale_sec: int = 0,
) -> tuple[Any, dict[str, Any]]:
    if marketplace == "wb" and _feedback_is_rate_limited(db, user_id=user_id, module_code=module_code, marketplace=marketplace):
        latest, latest_meta = _market_cache_latest_payload(
            db,
            user_id=user_id,
            module_code=module_code,
            marketplace=marketplace,
            max_age_sec=_FEEDBACK_STALE_FALLBACK_SEC,
        )
        if latest is not None:
            latest_meta = dict(latest_meta or {})
            latest_meta["source"] = "db-latest-rate-limit-pause"
            latest_meta["stale"] = True
            latest_meta["error"] = "WB API is paused after 429"
            return latest, latest_meta
        return _empty_feedback_rate_limit_payload(
            "WB временно ограничил запросы (429). Кэша пока нет, повторим загрузку после паузы."
        ), {
            "source": "empty-rate-limit-pause",
            "stale": True,
            "error": "WB API is paused after 429 and no cache is available",
        }
    try:
        return get_or_refresh_market_cache(
            db,
            user_id=user_id,
            module_code=module_code,
            marketplace=marketplace,
            cache_key=cache_key,
            ttl_sec=ttl_sec,
            fetcher=fetcher,
            stale_if_error_sec=stale_if_error_sec,
            prefer_stale_sec=prefer_stale_sec,
        )
    except WbRateLimitError as exc:
        _feedback_mark_rate_limited(db, user_id=user_id, module_code=module_code, marketplace=marketplace)
        latest, latest_meta = _market_cache_latest_payload(
            db,
            user_id=user_id,
            module_code=module_code,
            marketplace=marketplace,
            max_age_sec=_FEEDBACK_STALE_FALLBACK_SEC,
        )
        if latest is not None:
            latest_meta = dict(latest_meta or {})
            latest_meta["source"] = "db-latest-rate-limit-fallback"
            latest_meta["stale"] = True
            latest_meta["error"] = str(exc or "WB API returned 429")[:500]
            return latest, latest_meta
        return _empty_feedback_rate_limit_payload(
            "WB временно ограничил запросы (429). Кэша пока нет, повторим загрузку после паузы."
        ), {
            "source": "empty-rate-limit-fallback",
            "stale": True,
            "error": str(exc or "WB API returned 429")[:500],
        }


def _market_cache_latest_payload(
    db: Session,
    *,
    user_id: int,
    module_code: str,
    marketplace: str,
    max_age_sec: int = 24 * 60 * 60,
    exclude_cache_keys: set[str] | None = None,
    scan_limit: int = 80,
) -> tuple[dict[str, Any] | None, dict[str, Any]]:
    now = datetime.utcnow()
    excluded = {str(x or "").strip() for x in (exclude_cache_keys or set()) if str(x or "").strip()}
    rows = db.scalars(
        select(MarketplaceApiCache)
        .where(
            MarketplaceApiCache.user_id == int(user_id),
            MarketplaceApiCache.module_code == str(module_code or "").strip()[:80],
            MarketplaceApiCache.marketplace == str(marketplace or "").strip()[:30],
        )
        .order_by(MarketplaceApiCache.fetched_at.desc(), MarketplaceApiCache.id.desc())
        .limit(max(10, min(int(scan_limit or 80), 500)))
    ).all()
    for row in rows:
        if excluded and str(row.cache_key or "").strip() in excluded:
            continue
        fetched_at = row.fetched_at or row.last_hit_at
        if not fetched_at:
            continue
        age_sec = max(0, int((now - fetched_at).total_seconds()))
        if age_sec > max(60, int(max_age_sec or 0)):
            continue
        try:
            payload = json.loads(str(row.payload_json or ""))
        except Exception:
            continue
        if isinstance(payload, dict) and payload:
            return payload, {
                "source": "db-latest-module-fallback",
                "age_sec": age_sec,
                "cache_key": str(row.cache_key or ""),
            }
    return None, {}


def _warnings_indicate_upstream_failure(warnings: list[Any]) -> bool:
    raw = [str(x or "").strip().lower() for x in (warnings or []) if str(x or "").strip()]
    if not raw:
        return False
    markers = (
        "429",
        "rate_limited",
        "timed out",
        "timeout",
        "Р В Р’В Р В РІР‚В¦Р В Р’В Р вЂ™Р’ВµР В Р’В Р СћРІР‚ВР В Р’В Р РЋРІР‚СћР В Р Р‹Р В РЎвЂњР В Р Р‹Р Р†Р вЂљРЎв„ўР В Р Р‹Р РЋРІР‚СљР В Р’В Р РЋРІР‚вЂќ",
        "Р В Р’В Р РЋРІР‚СћР В Р Р‹Р Р†РІР‚С™Р’В¬Р В Р’В Р РЋРІР‚ВР В Р’В Р вЂ™Р’В±Р В Р’В Р РЋРІР‚СњР В Р’В Р вЂ™Р’В°",
        "error",
        "api Р В Р’В Р В РІР‚В Р В Р’В Р вЂ™Р’ВµР В Р Р‹Р В РІР‚С™Р В Р’В Р В РІР‚В¦Р В Р Р‹Р РЋРІР‚СљР В Р’В Р вЂ™Р’В»",
        "api Р В Р’В Р В РІР‚В¦Р В Р’В Р вЂ™Р’ВµР В Р’В Р СћРІР‚ВР В Р’В Р РЋРІР‚СћР В Р Р‹Р В РЎвЂњР В Р Р‹Р Р†Р вЂљРЎв„ўР В Р Р‹Р РЋРІР‚СљР В Р’В Р РЋРІР‚вЂќР В Р’В Р вЂ™Р’ВµР В Р’В Р В РІР‚В¦",
    )
    return any(any(mark in item for mark in markers) for item in raw)


def _sales_payload_has_data(payload: dict[str, Any] | None) -> bool:
    if not isinstance(payload, dict):
        return False
    rows = payload.get("rows")
    if isinstance(rows, list) and rows:
        return True
    totals = payload.get("totals") if isinstance(payload.get("totals"), dict) else {}
    numeric_keys = (
        "orders",
        "units",
        "buyouts",
        "revenue",
        "wb_orders",
        "ozon_orders",
        "wb_revenue",
        "ozon_revenue",
    )
    for key in numeric_keys:
        try:
            if abs(float(totals.get(key) or 0.0)) > 1e-9:
                return True
        except Exception:
            continue
    return False


_SALES_MARKET_METRICS = (
    "orders",
    "units",
    "buyouts",
    "order_amount",
    "buyout_amount",
    "revenue",
    "returns",
    "ad_spend",
    "penalties",
    "income",
    "expense",
    "net",
    "commission",
    "logistics",
    "storage",
    "deductions",
    "acceptance",
    "other_expense",
    "gross_profit",
)


def _sales_payload_has_market_data(payload: dict[str, Any] | None, marketplace: str) -> bool:
    if not isinstance(payload, dict):
        return False
    market = str(marketplace or "").strip().lower()
    rows = payload.get("rows")
    if isinstance(rows, list):
        for row in rows:
            if isinstance(row, dict) and str(row.get("marketplace") or "").strip().lower() == market:
                return True
    totals = payload.get("totals") if isinstance(payload.get("totals"), dict) else {}
    for key in _SALES_MARKET_METRICS:
        try:
            if abs(float(totals.get(f"{market}_{key}") or 0.0)) > 1e-9:
                return True
        except Exception:
            continue
    return False


def _sales_payload_for_market(payload: dict[str, Any] | None, marketplace: str) -> dict[str, Any] | None:
    if not isinstance(payload, dict):
        return None
    market = str(marketplace or "").strip().lower()
    rows = [
        _normalize_sales_market_row(dict(row), market)
        for row in (payload.get("rows") or [])
        if isinstance(row, dict) and str(row.get("marketplace") or "").strip().lower() == market
    ]
    totals_src = payload.get("totals") if isinstance(payload.get("totals"), dict) else {}
    totals = dict(totals_src)
    other_market = "ozon" if market == "wb" else "wb"
    for key in _SALES_MARKET_METRICS:
        totals[key] = totals_src.get(f"{market}_{key}", 0)
        totals[f"{other_market}_{key}"] = 0
    if market == "wb":
        _normalize_wb_sales_totals(totals)
    chart: list[dict[str, Any]] = []
    for point in (payload.get("chart") or []):
        if not isinstance(point, dict):
            continue
        next_point = dict(point)
        next_point["marketplace"] = market
        for key in _SALES_MARKET_METRICS:
            prefixed = f"{market}_{key}"
            if prefixed in point:
                next_point[key] = point.get(prefixed)
        chart.append(next_point)
    warnings = [str(x) for x in (payload.get("warnings") or [])]
    warnings.append(f"Показаны последние стабильные данные {market.upper()} из общего кеша из-за временного лимита API.")
    out = dict(payload)
    out["rows"] = rows
    out["chart"] = chart
    out["totals"] = totals
    out["warnings"] = list(dict.fromkeys([x for x in warnings if str(x).strip()]))
    return out


def _normalize_sales_market_row(row: dict[str, Any], marketplace: str) -> dict[str, Any]:
    market = str(marketplace or row.get("marketplace") or "").strip().lower()
    row["marketplace"] = market or row.get("marketplace")
    if market != "wb":
        return row
    orders = _to_int_safe(row.get("orders"))
    units = _to_int_safe(row.get("units"))
    buyouts = _to_int_safe(row.get("buyouts"))
    returns = _to_int_safe(row.get("returns"))
    if units <= 0 and buyouts > 0:
        units = buyouts
        row["units"] = units
    if orders <= 0 and (buyouts > 0 or returns > 0 or units > 0):
        row["orders"] = max(units, buyouts + returns, buyouts, returns)
    if _to_float_safe(row.get("order_amount")) <= 0 and _to_float_safe(row.get("revenue")) > 0:
        row["order_amount"] = row.get("revenue")
    return row


def _normalize_wb_sales_totals(totals: dict[str, Any]) -> None:
    orders = _to_int_safe(totals.get("orders"))
    units = _to_int_safe(totals.get("units"))
    buyouts = _to_int_safe(totals.get("buyouts"))
    returns = _to_int_safe(totals.get("returns"))
    if units <= 0 and buyouts > 0:
        units = buyouts
        totals["units"] = units
        totals["wb_units"] = units
    if orders <= 0 and (buyouts > 0 or returns > 0 or units > 0):
        orders = max(units, buyouts + returns, buyouts, returns)
        totals["orders"] = orders
        totals["wb_orders"] = orders
    if _to_float_safe(totals.get("order_amount")) <= 0 and _to_float_safe(totals.get("revenue")) > 0:
        totals["order_amount"] = totals.get("revenue")
        totals["wb_order_amount"] = totals.get("revenue")


def _merge_sales_market_payload(base: dict[str, Any], market_payload: dict[str, Any], marketplace: str) -> dict[str, Any]:
    if not isinstance(base, dict) or not isinstance(market_payload, dict):
        return base
    market = str(marketplace or "").strip().lower()
    out = dict(base)
    base_rows = [
        row
        for row in (out.get("rows") or [])
        if not (isinstance(row, dict) and str(row.get("marketplace") or "").strip().lower() == market)
    ]
    market_rows = [
        _normalize_sales_market_row(dict(row), market)
        for row in (market_payload.get("rows") or [])
        if isinstance(row, dict)
    ]
    out["rows"] = base_rows + market_rows

    totals = dict(out.get("totals") if isinstance(out.get("totals"), dict) else {})
    market_totals = dict(market_payload.get("totals") if isinstance(market_payload.get("totals"), dict) else {})
    if market == "wb":
        _normalize_wb_sales_totals(market_totals)
    int_metrics = {"orders", "units", "buyouts", "returns", "days"}
    for key in _SALES_MARKET_METRICS:
        value = market_totals.get(key, 0)
        totals[f"{market}_{key}"] = value
        if key in int_metrics:
            totals[key] = _to_int_safe(totals.get(key)) + _to_int_safe(value)
        else:
            totals[key] = float(round(_to_float_safe(totals.get(key)) + _to_float_safe(value), 2))
    totals[f"{market}_days"] = market_totals.get("days", totals.get(f"{market}_days", 0))
    out["totals"] = totals

    base_chart = [dict(x) for x in (out.get("chart") or []) if isinstance(x, dict)]
    market_chart = [dict(x) for x in (market_payload.get("chart") or []) if isinstance(x, dict)]
    if market_chart:
        by_key: dict[str, dict[str, Any]] = {}
        for point in base_chart:
            key = str(point.get("date") or point.get("time") or point.get("label") or len(by_key))
            by_key[key] = point
        for point in market_chart:
            key = str(point.get("date") or point.get("time") or point.get("label") or len(by_key))
            target = by_key.setdefault(key, {"date": point.get("date"), "time": point.get("time"), "label": point.get("label")})
            for metric in _SALES_MARKET_METRICS:
                prefixed = f"{market}_{metric}"
                value = point.get(prefixed, point.get(metric))
                if value is None:
                    continue
                target[prefixed] = value
                if metric in int_metrics:
                    target[metric] = _to_int_safe(target.get(metric)) + _to_int_safe(value)
                else:
                    target[metric] = float(round(_to_float_safe(target.get(metric)) + _to_float_safe(value), 2))
        out["chart"] = list(by_key.values())

    warnings = [str(x) for x in (out.get("warnings") or []) if str(x).strip()]
    warnings.extend(str(x) for x in (market_payload.get("warnings") or []) if str(x).strip())
    warnings.append(f"WB: показаны последние стабильные данные из кеша, потому что текущий запрос к API ограничен.")
    out["warnings"] = list(dict.fromkeys(warnings))
    return out


def _sales_latest_market_fallback_payload(
    db: Session,
    *,
    user_id: int,
    marketplace: str,
    max_age_sec: int = 7 * 24 * 60 * 60,
    exclude_cache_keys: set[str] | None = None,
    scan_limit: int = 180,
) -> tuple[dict[str, Any] | None, dict[str, Any]]:
    market = str(marketplace or "").strip().lower()
    now = datetime.utcnow()
    excluded = {str(x or "").strip() for x in (exclude_cache_keys or set()) if str(x or "").strip()}
    rows = db.scalars(
        select(MarketplaceApiCache)
        .where(
            MarketplaceApiCache.user_id == int(user_id),
            MarketplaceApiCache.module_code == "sales_stats",
            MarketplaceApiCache.marketplace == "all",
        )
        .order_by(MarketplaceApiCache.fetched_at.desc(), MarketplaceApiCache.id.desc())
        .limit(max(20, min(int(scan_limit or 180), 500)))
    ).all()
    for row in rows:
        if excluded and str(row.cache_key or "").strip() in excluded:
            continue
        fetched_at = row.fetched_at or row.last_hit_at
        if not fetched_at:
            continue
        age_sec = max(0, int((now - fetched_at).total_seconds()))
        if age_sec > max(60, int(max_age_sec or 0)):
            continue
        try:
            payload = json.loads(str(row.payload_json or ""))
        except Exception:
            continue
        if _sales_payload_has_market_data(payload if isinstance(payload, dict) else None, market):
            return _sales_payload_for_market(payload, market), {
                "source": f"db-latest-all-{market}-fallback",
                "age_sec": age_sec,
                "cache_key": str(row.cache_key or ""),
            }
    return None, {}


def _accounting_payload_has_data(payload: dict[str, Any] | None) -> bool:
    if not isinstance(payload, dict):
        return False
    overview = payload.get("overview") if isinstance(payload.get("overview"), dict) else {}
    numeric_keys = ("orders", "units", "buyouts", "revenue", "gross_profit", "net_profit")
    for key in numeric_keys:
        try:
            if abs(float(overview.get(key) or 0.0)) > 1e-9:
                return True
        except Exception:
            continue
    chart = payload.get("chart")
    if isinstance(chart, list):
        for row in chart:
            if not isinstance(row, dict):
                continue
            for key in ("orders", "units", "revenue", "gross_profit", "net_profit"):
                try:
                    if abs(float(row.get(key) or 0.0)) > 1e-9:
                        return True
                except Exception:
                    continue
    analysis_rows = payload.get("analysis_rows")
    if not isinstance(analysis_rows, list) or not analysis_rows:
        return False
    for row in analysis_rows:
        if not isinstance(row, dict):
            continue
        for key in (
            "orders",
            "units",
            "buyouts",
            "sold_units",
            "returns",
            "revenue",
            "gross_profit",
            "operating_profit",
            "net_profit",
            "marketplace_expenses",
            "cogs",
        ):
            try:
                if abs(float(row.get(key) or 0.0)) > 1e-9:
                    return True
            except Exception:
                continue
    return False


def _accounting_monthly_payload_has_data(payload: dict[str, Any] | None) -> bool:
    if not isinstance(payload, dict):
        return False
    months = payload.get("months")
    if not isinstance(months, list) or not months:
        return False
    for row in months:
        if not isinstance(row, dict):
            continue
        for section in ("wb", "ozon", "total"):
            part = row.get(section)
            if not isinstance(part, dict):
                continue
            for key in ("turnover", "orders", "units", "buyouts", "cogs", "net_profit"):
                try:
                    if abs(float(part.get(key) or 0.0)) > 1e-9:
                        return True
                except Exception:
                    continue
    return False


def _quick_accounting_monthly_from_sales_cache(
    sales_payload: dict[str, Any] | None,
    *,
    month_count: int,
    tz_name: str,
) -> dict[str, Any]:
    try:
        tzinfo = ZoneInfo(str(tz_name or "Europe/Moscow").strip() or "Europe/Moscow")
    except Exception:
        tzinfo = ZoneInfo("UTC")
    today = datetime.now(tzinfo).date()
    first_month = date(today.year, today.month, 1)

    def shift_month(month_start: date, delta: int) -> date:
        index = (month_start.year * 12 + month_start.month - 1) + int(delta)
        return date(index // 12, (index % 12) + 1, 1)

    def month_end(month_start: date) -> date:
        return shift_month(month_start, 1) - timedelta(days=1)

    def kpi() -> dict[str, Any]:
        return {
            "turnover": 0.0,
            "orders": 0,
            "units": 0,
            "buyouts": 0,
            "cogs": 0.0,
            "commission": 0.0,
            "acquiring": 0.0,
            "logistics": 0.0,
            "storage": 0.0,
            "penalties": 0.0,
            "ad_spend": 0.0,
            "marketplace_expense": 0.0,
            "custom_expenses": 0.0,
            "other_expenses": 0.0,
            "tax_amount": 0.0,
            "vat_amount": 0.0,
            "tax_total": 0.0,
            "operating_profit": 0.0,
            "net_profit": 0.0,
            "margin": 0.0,
        }

    def add_kpi(target: dict[str, Any], row: dict[str, Any]) -> None:
        target["turnover"] = round(float(target.get("turnover") or 0.0) + _to_float_safe(row.get("revenue"), 0.0), 2)
        target["orders"] = int(target.get("orders") or 0) + _to_int_safe(row.get("orders"))
        target["units"] = int(target.get("units") or 0) + _to_int_safe(row.get("units"))
        target["buyouts"] = int(target.get("buyouts") or 0) + _to_int_safe(row.get("buyouts"))
        for key in ("commission", "logistics", "storage", "penalties", "ad_spend", "other_expenses"):
            source_key = "other_expense" if key == "other_expenses" else key
            target[key] = round(float(target.get(key) or 0.0) + _to_float_safe(row.get(source_key), 0.0), 2)
        expense = sum(_to_float_safe(target.get(key), 0.0) for key in ("commission", "logistics", "storage", "penalties", "ad_spend", "other_expenses"))
        target["marketplace_expense"] = round(expense, 2)
        target["operating_profit"] = round(_to_float_safe(target.get("turnover"), 0.0) - expense, 2)
        target["net_profit"] = target["operating_profit"]
        turnover = _to_float_safe(target.get("turnover"), 0.0)
        target["margin"] = round((target["net_profit"] / turnover) * 100, 2) if turnover > 0 else 0.0

    months: list[dict[str, Any]] = []
    index_by_key: dict[str, dict[str, Any]] = {}
    for offset in range(max(1, min(12, int(month_count or 12)))):
        start = shift_month(first_month, -offset)
        key = f"{start.year:04d}-{start.month:02d}"
        row = {
            "month_key": key,
            "label": key,
            "date_from": start.isoformat(),
            "date_to": month_end(start).isoformat(),
            "wb": kpi(),
            "ozon": kpi(),
            "total": kpi(),
        }
        months.append(row)
        index_by_key[key] = row

    rows = list((sales_payload or {}).get("rows") or []) if isinstance(sales_payload, dict) else []
    for item in rows:
        if not isinstance(item, dict):
            continue
        mp = str(item.get("marketplace") or "").strip().lower()
        if mp not in {"wb", "ozon"}:
            continue
        day_text = str(item.get("date") or item.get("occurred_at") or "").strip()[:10]
        try:
            day = date.fromisoformat(day_text)
        except Exception:
            continue
        slot = index_by_key.get(f"{day.year:04d}-{day.month:02d}")
        if not slot:
            continue
        add_kpi(slot[mp], item)
        add_kpi(slot["total"], item)

    return {
        "months": months,
        "meta": {
            "source": "sales-cache-fastpath",
            "partial": True,
            "warnings": ["Показан быстрый расчет по последнему кэшу продаж. Полная бухгалтерская детализация обновится после фоновой загрузки."],
            "generated_at": datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
        },
    }


def _accounting_payload_needs_finance_fallback(payload: dict[str, Any] | None, warnings: list[str] | None = None) -> bool:
    if not isinstance(payload, dict):
        return False
    warning_text = " | ".join(str(x or "").strip().lower() for x in (warnings or []))
    if not warning_text:
        return False
    markers = (
        "finance api Р В Р’В Р В РІР‚В¦Р В Р’В Р вЂ™Р’ВµР В Р’В Р СћРІР‚ВР В Р’В Р РЋРІР‚СћР В Р Р‹Р В РЎвЂњР В Р Р‹Р Р†Р вЂљРЎв„ўР В Р Р‹Р РЋРІР‚СљР В Р’В Р РЋРІР‚вЂќР В Р’В Р вЂ™Р’ВµР В Р’В Р В РІР‚В¦",
        "finance api unavailable",
        "Р В Р Р‹Р В РІР‚С™Р В Р’В Р вЂ™Р’ВµР В Р’В Р РЋРІР‚СњР В Р’В Р вЂ™Р’В»Р В Р’В Р вЂ™Р’В°Р В Р’В Р РЋР’ВР В Р’В Р В РІР‚В¦Р В Р Р‹Р Р†Р вЂљРІвЂћвЂ“Р В Р’В Р вЂ™Р’Вµ Р В Р Р‹Р В РІР‚С™Р В Р’В Р вЂ™Р’В°Р В Р Р‹Р В РЎвЂњР В Р Р‹Р Р†Р вЂљР’В¦Р В Р’В Р РЋРІР‚СћР В Р’В Р СћРІР‚ВР В Р Р‹Р Р†Р вЂљРІвЂћвЂ“ Р В Р’В Р В РІР‚В Р В Р Р‹Р В РІР‚С™Р В Р’В Р вЂ™Р’ВµР В Р’В Р РЋР’ВР В Р’В Р вЂ™Р’ВµР В Р’В Р В РІР‚В¦Р В Р’В Р В РІР‚В¦Р В Р’В Р РЋРІР‚Сћ Р В Р’В Р В РІР‚В¦Р В Р’В Р вЂ™Р’ВµР В Р’В Р СћРІР‚ВР В Р’В Р РЋРІР‚СћР В Р Р‹Р В РЎвЂњР В Р Р‹Р Р†Р вЂљРЎв„ўР В Р Р‹Р РЋРІР‚СљР В Р’В Р РЋРІР‚вЂќР В Р’В Р В РІР‚В¦Р В Р Р‹Р Р†Р вЂљРІвЂћвЂ“",
        "rate_limited",
        "Р В Р’В Р РЋРІР‚СћР В Р’В Р РЋРІР‚вЂњР В Р Р‹Р В РІР‚С™Р В Р’В Р вЂ™Р’В°Р В Р’В Р В РІР‚В¦Р В Р’В Р РЋРІР‚ВР В Р Р‹Р Р†Р вЂљР Р‹Р В Р’В Р РЋРІР‚ВР В Р’В Р вЂ™Р’В» Р В Р’В Р вЂ™Р’В·Р В Р’В Р вЂ™Р’В°Р В Р’В Р РЋРІР‚вЂќР В Р Р‹Р В РІР‚С™Р В Р’В Р РЋРІР‚СћР В Р Р‹Р В РЎвЂњР В Р Р‹Р Р†Р вЂљРІвЂћвЂ“",
    )
    if not any(marker in warning_text for marker in markers):
        return False

    overview = payload.get("overview") if isinstance(payload.get("overview"), dict) else {}
    revenue = abs(float(_to_float_safe(overview.get("revenue"), 0.0)))
    if revenue <= 1e-9:
        return False

    for key in (
        "cogs",
        "marketplace_expense",
        "marketplace_expenses",
        "gross_profit",
        "operating_profit",
        "net_profit",
        "ads",
        "ad_spent",
        "commissions",
        "logistics",
    ):
        if abs(float(_to_float_safe(overview.get(key), 0.0))) > 1e-9:
            return False

    analysis_rows = payload.get("analysis_rows")
    if isinstance(analysis_rows, list):
        for row in analysis_rows:
            if not isinstance(row, dict):
                continue
            for key in ("cogs", "marketplace_expense", "marketplace_expenses", "gross_profit", "operating_profit", "net_profit"):
                if abs(float(_to_float_safe(row.get(key), 0.0))) > 1e-9:
                    return False

    return True


def _extract_returns_payload_rows(payload: Any) -> list[dict[str, Any]]:
    def _path_value(root: Any, path: str) -> Any:
        current = root
        for part in str(path or "").split("."):
            key = str(part or "").strip()
            if not key or not isinstance(current, dict):
                return None
            current = current.get(key)
        return current

    def _append_rows(out: list[dict[str, Any]], node: Any) -> None:
        if isinstance(node, list):
            for item in node:
                if isinstance(item, dict):
                    out.append(item)

    def _looks_like_return_row(node: Any) -> bool:
        if not isinstance(node, dict):
            return False
        keys = {str(key or "").strip().lower() for key in node.keys()}
        if {"claim", "return", "item", "product"} & keys:
            return True
        id_keys = {
            "id",
            "return_id",
            "returnid",
            "claimid",
            "claim_id",
            "posting_number",
            "srid",
            "order_id",
        }
        info_keys = {
            "status",
            "state",
            "created_at",
            "createdat",
            "updated_at",
            "updatedat",
            "name",
            "product",
            "reason",
            "comment",
            "description",
        }
        return bool(keys & id_keys) and bool(keys & info_keys)

    rows: list[dict[str, Any]] = []
    if isinstance(payload, list):
        _append_rows(rows, payload)
        return rows
    if not isinstance(payload, dict):
        return rows

    for path in (
        "rows",
        "claims",
        "returns",
        "items",
        "data.rows",
        "data.claims",
        "data.returns",
        "data.items",
        "result.rows",
        "result.claims",
        "result.returns",
        "result.items",
        "payload.rows",
        "payload.claims",
        "payload.returns",
        "payload.items",
        "response.rows",
        "response.claims",
        "response.returns",
        "response.items",
        "data.result.rows",
        "data.result.claims",
        "data.result.returns",
        "result.data.rows",
        "result.data.claims",
        "result.data.returns",
    ):
        _append_rows(rows, _path_value(payload, path))

    if rows:
        return rows

    for node in (payload.get("data"), payload.get("result"), payload.get("payload"), payload.get("response")):
        if isinstance(node, list):
            _append_rows(rows, node)
            if rows:
                return rows

    if _looks_like_return_row(payload):
        return [payload]
    return rows


def _normalize_returns_rows(rows: list[dict[str, Any]], marketplace: str) -> list[dict[str, Any]]:
    safe_market = str(marketplace or "").strip().lower()
    out: list[dict[str, Any]] = []
    seen: set[str] = set()

    def _path_value(root: Any, path: str) -> Any:
        current = root
        for part in str(path or "").split("."):
            key = str(part or "").strip()
            if not key or not isinstance(current, dict):
                return None
            current = current.get(key)
        return current

    def _clean_text(value: Any) -> str:
        if isinstance(value, (dict, list, tuple, set)):
            return ""
        text = " ".join(str(value or "").split()).strip()
        low = text.lower()
        if not text or low in {"-", "Р В Р вЂ Р В РІР‚С™Р Р†Р вЂљРЎСљ", "null", "none", "undefined", "n/a"}:
            return ""
        return text

    def _pick_text(node: dict[str, Any], *paths: str) -> str:
        for path in paths:
            text = _clean_text(_path_value(node, path))
            if text:
                return text
        return ""

    def _number_from(value: Any) -> float | None:
        if isinstance(value, bool):
            return None
        if isinstance(value, (int, float)):
            num = float(value)
            return num if math.isfinite(num) else None
        if isinstance(value, str):
            text = str(value or "").strip()
            if not text:
                return None
            normalized = text.replace("\xa0", " ").replace(" ", "")
            normalized = normalized.replace("?", "").replace("Р В Р Р‹Р В РІР‚С™Р В Р Р‹Р РЋРІР‚СљР В Р’В Р вЂ™Р’В±.", "").replace("Р В Р Р‹Р В РІР‚С™Р В Р Р‹Р РЋРІР‚СљР В Р’В Р вЂ™Р’В±", "")
            normalized = normalized.replace(",", ".")
            match = re.search(r"-?\d+(?:\.\d+)?", normalized)
            if not match:
                return None
            try:
                num = float(match.group(0))
                return num if math.isfinite(num) else None
            except Exception:
                return None
        if isinstance(value, dict):
            for key in ("value", "amount", "price", "sum", "total", "qty", "count", "quantity"):
                if key in value:
                    parsed = _number_from(value.get(key))
                    if parsed is not None:
                        return parsed
            for nested in value.values():
                parsed = _number_from(nested)
                if parsed is not None:
                    return parsed
            return None
        if isinstance(value, (list, tuple)):
            for item in value:
                parsed = _number_from(item)
                if parsed is not None:
                    return parsed
            return None
        return None

    def _format_number(value: float | None) -> str:
        if value is None or not math.isfinite(value):
            return ""
        rounded = round(float(value), 3)
        if abs(rounded - round(rounded)) < 0.000001:
            return str(int(round(rounded)))
        text = f"{rounded:.3f}".rstrip("0").rstrip(".")
        return text

    def _pick_number_text(node: dict[str, Any], *paths: str) -> str:
        for path in paths:
            number = _number_from(_path_value(node, path))
            text = _format_number(number)
            if text:
                return text
        return ""

    def _clean_photo(*values: Any) -> list[str]:
        photos: list[str] = []
        seen_photo: set[str] = set()

        def _walk(node: Any, depth: int = 0) -> None:
            if node is None or depth > 4:
                return
            if isinstance(node, str):
                url = str(node or "").strip()
                if not url or url in seen_photo:
                    return
                if not (url.startswith("http://") or url.startswith("https://")):
                    return
                seen_photo.add(url)
                photos.append(url)
                return
            if isinstance(node, list):
                for item in node:
                    _walk(item, depth + 1)
                return
            if isinstance(node, dict):
                for key in ("url", "photo", "image", "src", "link", "href", "path", "big", "x1", "x2", "orig", "tm"):
                    _walk(node.get(key), depth + 1)
                for key, value in node.items():
                    if re.search(r"(photo|image|picture|attachment|file|evidence)", str(key or ""), flags=re.IGNORECASE):
                        _walk(value, depth + 1)
                return

        for value in values:
            _walk(value, 0)
        return photos

    def _join_lines(*values: Any) -> str:
        lines: list[str] = []
        seen_lines: set[str] = set()
        for value in values:
            text = _clean_text(value)
            if not text:
                continue
            low = text.lower()
            if low in seen_lines:
                continue
            seen_lines.add(low)
            lines.append(text)
        return "\n".join(lines)

    for row in rows:
        if not isinstance(row, dict):
            continue
        raw_node = row.get("raw") if isinstance(row.get("raw"), dict) else {}
        merged = dict(raw_node)
        for key, value in row.items():
            if key not in merged or merged.get(key) in (None, "", [], {}):
                merged[key] = value

        rid = _pick_text(
            merged,
            "id",
            "return_id",
            "returnId",
            "claimId",
            "claim_id",
            "claim.id",
            "claim.claimId",
            "return.id",
            "return.return_id",
            "posting_number",
            "posting.number",
            "srid",
            "order_id",
            "returnNumber",
        )
        status = _pick_text(
            merged,
            "status",
            "state",
            "claimStatus",
            "claim.status",
            "claim.state",
            "return.status",
            "return.state",
            "status.name",
            "state.name",
            "claim.status.name",
            "return.status.name",
        )
        status_code = _pick_text(
            merged,
            "status_code",
            "statusCode",
            "status.id",
            "status.code",
            "state.id",
            "state.code",
            "claim.status.id",
            "claim.status.code",
            "return.status.id",
            "return.status.code",
        )
        status_note = _pick_text(
            merged,
            "status_ex",
            "statusEx",
            "status_detail",
            "statusDetail",
            "status.note",
            "status.description",
            "decision_comment",
            "rejectReason",
            "reject_reason",
            "claim.status.note",
            "claim.status.description",
            "return.status.note",
            "return.status.description",
        )
        created_at = _pick_text(
            merged,
            "created_at",
            "createdAt",
            "date",
            "createdDate",
            "claim.createdAt",
            "return.createdAt",
        )
        updated_at = _pick_text(
            merged,
            "updated_at",
            "updatedAt",
            "status_updated_at",
            "statusUpdatedAt",
            "claim.updatedAt",
            "return.updatedAt",
        )
        vendor_code = _pick_text(
            merged,
            "vendor_code",
            "vendorCode",
            "supplierVendorCode",
            "origin_id_info.vendor_code",
            "item.vendorCode",
            "claim.item.vendorCode",
            "return.item.vendorCode",
        )
        nm_id = _pick_text(
            merged,
            "nm_id",
            "nmId",
            "imt_id",
            "imtId",
            "item.nm_id",
            "claim.item.nm_id",
            "return.item.nm_id",
        )
        article = _pick_text(
            merged,
            "article",
            "offer_id",
            "offerId",
            "sku",
            "vendorCode",
            "supplierVendorCode",
            "item.article",
            "item.offer_id",
            "claim.item.article",
            "return.item.article",
            "product.article",
            "product.offer_id",
        )
        product = _pick_text(
            merged,
            "product",
            "product_name",
            "productName",
            "name",
            "subjectName",
            "imtName",
            "item.name",
            "item.title",
            "claim.item.name",
            "return.item.name",
            "product.name",
        )
        quantity = _pick_number_text(
            merged,
            "quantity",
            "count",
            "itemsCount",
            "qty",
            "item.quantity",
            "claim.item.quantity",
            "return.item.quantity",
        )
        amount = _pick_number_text(
            merged,
            "amount",
            "sum",
            "total",
            "refundAmount",
            "returnAmount",
            "price",
            "claim.amount",
            "claim.price",
            "return.amount",
            "return.price",
            "item.price",
        )
        customer_comment = _pick_text(
            merged,
            "user_comment",
            "customer_comment",
            "comment",
            "claim.comment",
            "return.comment",
        )
        seller_comment = _pick_text(
            merged,
            "seller_comment",
            "wb_comment",
            "decision_comment",
            "rejectReason",
            "reject_reason",
            "claim.decision_comment",
            "return.decision_comment",
        )
        base_reason = _pick_text(
            merged,
            "description",
            "reason",
            "text",
            "comment",
            "rejectReason",
            "reject_reason",
            "claim.reason",
            "claim.description",
            "return.reason",
            "return.description",
        )
        reason = _join_lines(base_reason, status_note, customer_comment, seller_comment)
        photos = _clean_photo(
            merged.get("photos"),
            merged.get("images"),
            merged.get("pictures"),
            merged.get("attachments"),
            merged.get("files"),
            merged.get("evidences"),
            merged.get("claim"),
            merged.get("return"),
            merged.get("item"),
            merged.get("product"),
        )
        if not rid:
            fingerprint = "|".join(
                [
                    created_at,
                    updated_at,
                    vendor_code,
                    nm_id,
                    article,
                    product,
                    status,
                    reason,
                ]
            ).strip("|")
            if fingerprint:
                rid = hashlib.sha1(fingerprint.encode("utf-8", errors="ignore")).hexdigest()[:16]
        if not any([rid, status, status_code, created_at, updated_at, article, product, reason, photos, amount, quantity]):
            continue
        if not rid or rid in seen:
            continue
        seen.add(rid)
        out.append(
            {
                "id": rid,
                "status": status or status_code,
                "status_code": status_code or status,
                "status_note": status_note,
                "created_at": created_at,
                "updated_at": updated_at,
                "date": created_at,
                "article": article,
                "vendor_code": vendor_code,
                "nm_id": nm_id,
                "product": product,
                "quantity": quantity,
                "amount": amount,
                "customer_comment": customer_comment,
                "seller_comment": seller_comment,
                "reason": reason,
                "description": reason,
                "photos": photos,
                "marketplace": safe_market or str(merged.get("marketplace") or "").strip().lower(),
                "raw": raw_node if raw_node else merged,
            }
        )
    return out


def _enqueue_sales_cache_warmup(
    user_id: int,
    *,
    marketplace: str,
    date_from: date,
    date_to: date,
    granularity: str,
    tz_name: str,
) -> dict[str, Any]:
    return enqueue_task(
        "warm_sales_cache",
        {
            "user_id": int(user_id),
            "marketplace": str(marketplace or "all").strip().lower(),
            "date_from": date_from.isoformat(),
            "date_to": date_to.isoformat(),
            "granularity": str(granularity or "auto").strip().lower(),
            "tz": str(tz_name or "UTC").strip() or "UTC",
        },
        dedupe_key=(
            f"warm_sales:{int(user_id)}:{str(marketplace or 'all').strip().lower()}:"
            f"{date_from.isoformat()}:{date_to.isoformat()}:{str(granularity or 'auto').strip().lower()}:{str(tz_name or 'UTC').strip()}"
        ),
        dedupe_ttl_sec=90,
    )

