@router.post("/keywords", response_model=KeywordOut)
def add_keyword(payload: KeywordIn, user: User = Depends(get_current_user), db: Session = Depends(get_db)):
    marketplace = payload.marketplace.strip().lower()
    if marketplace not in {"all", "wb", "ozon"}:
        raise HTTPException(status_code=400, detail="marketplace Р В Р’В Р СћРІР‚ВР В Р’В Р РЋРІР‚СћР В Р’В Р вЂ™Р’В»Р В Р’В Р вЂ™Р’В¶Р В Р’В Р вЂ™Р’ВµР В Р’В Р В РІР‚В¦ Р В Р’В Р вЂ™Р’В±Р В Р Р‹Р Р†Р вЂљРІвЂћвЂ“Р В Р Р‹Р Р†Р вЂљРЎв„ўР В Р Р‹Р В Р вЂ° all, wb Р В Р’В Р РЋРІР‚ВР В Р’В Р вЂ™Р’В»Р В Р’В Р РЋРІР‚В ozon")
    keyword = payload.keyword.strip()
    if not keyword:
        raise HTTPException(status_code=400, detail="Р В Р’В Р РЋРІвЂћСћР В Р’В Р вЂ™Р’В»Р В Р Р‹Р В РІР‚в„–Р В Р Р‹Р Р†Р вЂљР Р‹Р В Р’В Р вЂ™Р’ВµР В Р’В Р В РІР‚В Р В Р’В Р РЋРІР‚СћР В Р’В Р вЂ™Р’Вµ Р В Р Р‹Р В РЎвЂњР В Р’В Р вЂ™Р’В»Р В Р’В Р РЋРІР‚СћР В Р’В Р В РІР‚В Р В Р’В Р РЋРІР‚Сћ Р В Р’В Р В РІР‚В¦Р В Р’В Р вЂ™Р’Вµ Р В Р’В Р СћРІР‚ВР В Р’В Р РЋРІР‚СћР В Р’В Р вЂ™Р’В»Р В Р’В Р вЂ™Р’В¶Р В Р’В Р В РІР‚В¦Р В Р’В Р РЋРІР‚Сћ Р В Р’В Р вЂ™Р’В±Р В Р Р‹Р Р†Р вЂљРІвЂћвЂ“Р В Р Р‹Р Р†Р вЂљРЎв„ўР В Р Р‹Р В Р вЂ° Р В Р’В Р РЋРІР‚вЂќР В Р Р‹Р РЋРІР‚СљР В Р Р‹Р В РЎвЂњР В Р Р‹Р Р†Р вЂљРЎв„ўР В Р Р‹Р Р†Р вЂљРІвЂћвЂ“Р В Р’В Р РЋР’В")

    exists = db.scalar(
        select(UserKeyword).where(
            UserKeyword.user_id == user.id,
            UserKeyword.marketplace == marketplace,
            UserKeyword.keyword == keyword,
            _owned_by_actor_or_owner_filter(UserKeyword, user),
        )
    )
    if exists:
        return exists

    row = UserKeyword(user_id=user.id, marketplace=marketplace, keyword=keyword)
    _assign_owner_member(row, _resolve_owner_member_id(db, user))
    db.add(row)
    _audit(
        db,
        user,
        action="keyword_added",
        details=f"marketplace={marketplace};keyword={keyword}",
        module_code="seo_generation",
        entity_type="keyword",
    )
    db.commit()
    db.refresh(row)
    return row


