    if not row:
        raise HTTPException(status_code=404, detail="Р В Р’В Р Р†Р вЂљРІР‚СњР В Р’В Р вЂ™Р’В°Р В Р Р‹Р В Р РЏР В Р’В Р В РІР‚В Р В Р’В Р РЋРІР‚СњР В Р’В Р вЂ™Р’В° Р В Р’В Р В РІР‚В¦Р В Р’В Р вЂ™Р’В° Р В Р’В Р В РІР‚В Р В Р’В Р РЋРІР‚СћР В Р’В Р вЂ™Р’В·Р В Р’В Р В РІР‚В Р В Р Р‹Р В РІР‚С™Р В Р’В Р вЂ™Р’В°Р В Р Р‹Р Р†Р вЂљРЎв„ў Р В Р’В Р В РІР‚В¦Р В Р’В Р вЂ™Р’Вµ Р В Р’В Р В РІР‚В¦Р В Р’В Р вЂ™Р’В°Р В Р’В Р Р†РІР‚С›РІР‚вЂњР В Р’В Р СћРІР‚ВР В Р’В Р вЂ™Р’ВµР В Р’В Р В РІР‚В¦Р В Р’В Р вЂ™Р’В°")
    normalized = _normalize_returns_rows([row], "ozon")
    if normalized:
        safe = dict(row)
        norm = normalized[0]
        for key in ("id", "status", "status_code", "status_note", "created_at", "updated_at", "date", "article", "vendor_code", "nm_id", "product", "quantity", "amount", "customer_comment", "seller_comment", "reason", "description", "photos", "marketplace"):
            if key in norm and norm.get(key) not in (None, "", [], {}):
                safe[key] = norm.get(key)
        safe["description"] = str(safe.get("reason") or safe.get("description") or "")
        safe["raw"] = row
        row = safe
