@router.post("/wb/ads/bidder/rules", response_model=WbBidderRuleOut)
def wb_ads_bidder_rules_create(
    payload: WbBidderRuleIn,
    user: User = Depends(get_current_user),
    db: Session = Depends(get_db),
):
    ensure_module_enabled(db, user, "wb_ads")
    try:
        normalized = normalize_rule_payload(payload.model_dump())
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc))
    row = WbAdsBidderRule(user_id=int(user.id), **normalized)
    db.add(row)
    db.flush()
    serialized = serialize_bidder_rule(row)
    _audit(
        db,
        user,
        action="wb_ads_bidder_rule_created",
        details=f"rule_id={row.id};campaign_id={row.campaign_id};target_kind={row.target_kind};nm_id={row.nm_id};active={int(row.is_active)}",
        module_code="wb_ads",
        entity_type="bidder_rule",
        entity_id=str(row.id),
    )
    try:
        db.commit()
    except Exception as exc:
        db.rollback()
        low = str(exc or "").lower()
        if "uq_wb_ads_bidder_rule_target" in low or "unique" in low:
            raise HTTPException(status_code=400, detail="Р В Р’В Р РЋРЎвЂєР В Р’В Р вЂ™Р’В°Р В Р’В Р РЋРІР‚СњР В Р’В Р РЋРІР‚СћР В Р’В Р вЂ™Р’Вµ Р В Р’В Р РЋРІР‚вЂќР В Р Р‹Р В РІР‚С™Р В Р’В Р вЂ™Р’В°Р В Р’В Р В РІР‚В Р В Р’В Р РЋРІР‚ВР В Р’В Р вЂ™Р’В»Р В Р’В Р РЋРІР‚Сћ Р В Р Р‹Р РЋРІР‚СљР В Р’В Р вЂ™Р’В¶Р В Р’В Р вЂ™Р’Вµ Р В Р Р‹Р В РЎвЂњР В Р Р‹Р РЋРІР‚СљР В Р Р‹Р Р†Р вЂљР’В°Р В Р’В Р вЂ™Р’ВµР В Р Р‹Р В РЎвЂњР В Р Р‹Р Р†Р вЂљРЎв„ўР В Р’В Р В РІР‚В Р В Р Р‹Р РЋРІР‚СљР В Р’В Р вЂ™Р’ВµР В Р Р‹Р Р†Р вЂљРЎв„ў")
