@router.patch("/wb/ads/bidder/rules/{rule_id}", response_model=WbBidderRuleOut)
def wb_ads_bidder_rules_update(
    rule_id: int,
    payload: WbBidderRuleUpdateIn,
    user: User = Depends(get_current_user),
    db: Session = Depends(get_db),
):
    ensure_module_enabled(db, user, "wb_ads")
    row = db.scalar(
        select(WbAdsBidderRule).where(
            WbAdsBidderRule.user_id == int(user.id),
            WbAdsBidderRule.id == int(rule_id),
        )
    )
    if not row:
        raise HTTPException(status_code=404, detail="Р В Р’В Р РЋРЎСџР В Р Р‹Р В РІР‚С™Р В Р’В Р вЂ™Р’В°Р В Р’В Р В РІР‚В Р В Р’В Р РЋРІР‚ВР В Р’В Р вЂ™Р’В»Р В Р’В Р РЋРІР‚Сћ Р В Р’В Р В РІР‚В¦Р В Р’В Р вЂ™Р’Вµ Р В Р’В Р В РІР‚В¦Р В Р’В Р вЂ™Р’В°Р В Р’В Р Р†РІР‚С›РІР‚вЂњР В Р’В Р СћРІР‚ВР В Р’В Р вЂ™Р’ВµР В Р’В Р В РІР‚В¦Р В Р’В Р РЋРІР‚Сћ")
    raw_patch = payload.model_dump(exclude_unset=True)
    if not raw_patch:
        return WbBidderRuleOut(**serialize_bidder_rule(row))
    current = {
        "campaign_id": row.campaign_id,
        "target_kind": row.target_kind,
        "nm_id": row.nm_id,
        "target_value": row.target_value,
        "placement": row.placement,
        "strategy": row.strategy,
        "desired_bid": row.desired_bid,
        "min_bid": row.min_bid,
        "max_bid": row.max_bid,
        "step_bid": row.step_bid,
        "target_pos_from": row.target_pos_from,
        "target_pos_to": row.target_pos_to,
        "min_clicks": row.min_clicks,
        "is_active": row.is_active,
        "cooldown_sec": row.cooldown_sec,
        "notes": row.notes,
    }
    try:
        normalized = normalize_rule_payload(raw_patch, partial=True, current=current)
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc))
    apply_rule_payload(row, normalized)
    serialized = serialize_bidder_rule(row)
    _audit(
        db,
        user,
        action="wb_ads_bidder_rule_updated",
        details=f"rule_id={row.id};fields={','.join(sorted(normalized.keys()))[:300]}",
        module_code="wb_ads",
        entity_type="bidder_rule",
        entity_id=str(row.id),
    )
    try:
        db.commit()
    except Exception as exc:
        db.rollback()
        low = str(exc or "").lower()
        if "uq_wb_ads_bidder_rule_target" in low or "unique" in low:
            raise HTTPException(status_code=400, detail="Р В Р’В Р РЋРЎвЂєР В Р’В Р вЂ™Р’В°Р В Р’В Р РЋРІР‚СњР В Р’В Р РЋРІР‚СћР В Р’В Р вЂ™Р’Вµ Р В Р’В Р РЋРІР‚вЂќР В Р Р‹Р В РІР‚С™Р В Р’В Р вЂ™Р’В°Р В Р’В Р В РІР‚В Р В Р’В Р РЋРІР‚ВР В Р’В Р вЂ™Р’В»Р В Р’В Р РЋРІР‚Сћ Р В Р Р‹Р РЋРІР‚СљР В Р’В Р вЂ™Р’В¶Р В Р’В Р вЂ™Р’Вµ Р В Р Р‹Р В РЎвЂњР В Р Р‹Р РЋРІР‚СљР В Р Р‹Р Р†Р вЂљР’В°Р В Р’В Р вЂ™Р’ВµР В Р Р‹Р В РЎвЂњР В Р Р‹Р Р†Р вЂљРЎв„ўР В Р’В Р В РІР‚В Р В Р Р‹Р РЋРІР‚СљР В Р’В Р вЂ™Р’ВµР В Р Р‹Р Р†Р вЂљРЎв„ў")
        raise
    return WbBidderRuleOut(**serialized)


